export const HOA12_CHUONG4_HANDBOOK = [{"title":"1. Phân Loại Tơ Cần Nhớ Chuẩn Tuyệt Đối","icon":"🧶","content":["<b>Tơ thiên nhiên:</b> Bông, len, tơ tằm.","<b>Tơ nhân tạo (bán tổng hợp):</b> Tơ visco, tơ cellulose acetate (luôn có chữ 'cellulose' hoặc 'visco').","<b>Tơ tổng hợp:</b> Tơ polyamide (nylon-6, nylon-7, nylon-6,6), tơ vinylic (tơ nitron/olon), tơ polyester (tơ lapsan)."]},{"title":"2. Cấu Trúc Không Gian Của Polymer","icon":"🔬","content":["<b>Mạng không gian:</b> Cao su lưu hóa, nhựa bakelite (rezit).","<b>Mạch phân nhánh:</b> Amylopectin (trong tinh bột), glycogen.","<b>Mạch không phân nhánh (mạch thẳng):</b> Tất cả các polymer còn lại (PE, PVC, cellulose, amylose, nylon...)."]},{"title":"3. Phản Ứng Trùng Hợp vs Trùng Ngưng","icon":"⚖️","content":["<b>Trùng hợp (cần liên kết đôi hoặc vòng kém bền):</b> PE, PP, PVC, PS, PMMA (plexiglas), Teflon, Cao su buna, Buna-S, Buna-N, Tơ nitron.","<b>Trùng ngưng (cần từ 2 nhóm chức trở lên, giải phóng H<sub>2</sub>O):</b> Nylon-6,6, Tơ lapsan, Tơ enang (nylon-7), Keo dán urea-formaldehyde."]}];

export class Hoa12Chuong4Service {
  static getAllLessons(): Chuong4Lesson[] {
    return HOA12_CHUONG4_LESSONS;
  }

  static getLessonById(id: string): Chuong4Lesson | undefined {
    return HOA12_CHUONG4_LESSONS.find(l => l.id === id);
  }

  static getAllExams(): Chuong4Exam[] {
    return HOA12_CHUONG4_EXAMS;
  }

  static getExamById(id: string): Chuong4Exam | undefined {
    return HOA12_CHUONG4_EXAMS.find(e => e.id === id);
  }

  static getHandbook() {
    return HOA12_CHUONG4_HANDBOOK;
  }
}

export interface Chuong4ExamAttempt {
  examId: string;
  examCode: string;
  score: number;
  totalQuestions: number;
  correctCount: number;
  durationSeconds: number;
  date: string;
  userAnswers?: Record<string | number, any>;
}

export interface Chuong4UserProgress {
  completedLessons: string[];
  examScores: Record<string, { score: number; date: string; attempts: number }>;
  savedNotes: Record<string, string>;
  totalXP: number;
  lastActiveDate: string;
  rankTitle: string;
}

const STORAGE_PREFIX = "hoa12_c4_";

export function getChuong4UserProgress(): Chuong4UserProgress {
  try {
    const raw = localStorage.getItem(`${STORAGE_PREFIX}progress`);
    if (raw) return JSON.parse(raw);
  } catch (e) {}
  return {
    completedLessons: [],
    examScores: {},
    savedNotes: {},
    totalXP: 0,
    lastActiveDate: new Date().toISOString(),
    rankTitle: "Tân Binh Polymer"
  };
}

export function saveChuong4ExamResult(examId: string, score: number): Chuong4UserProgress {
  const progress = getChuong4UserProgress();
  const current = progress.examScores[examId] || { score: 0, date: "", attempts: 0 };
  progress.examScores[examId] = {
    score: Math.max(current.score, score),
    date: new Date().toISOString(),
    attempts: current.attempts + 1
  };
  progress.totalXP += Math.round(score * 10);
  progress.lastActiveDate = new Date().toISOString();
  try {
    localStorage.setItem(`${STORAGE_PREFIX}progress`, JSON.stringify(progress));
  } catch (e) {}
  return progress;
}

export function saveChuong4ExamAttempt(attempt: Chuong4ExamAttempt): void {
  try {
    const key = `${STORAGE_PREFIX}exam_history`;
    const raw = localStorage.getItem(key);
    const history: Chuong4ExamAttempt[] = raw ? JSON.parse(raw) : [];
    history.unshift(attempt);
    if (history.length > 50) history.pop();
    localStorage.setItem(key, JSON.stringify(history));
  } catch (e) {}
}

export function getChuong4ExamHistory(): Chuong4ExamAttempt[] {
  try {
    const key = `${STORAGE_PREFIX}exam_history`;
    return key ? JSON.parse(localStorage.getItem(key) || "[]") : [];
  } catch (e) {}
  return [];
}

export function calculateChuong4ExamScore(exam: Chuong4Exam, userAnswers: Record<string, any>) {
  let totalScore = 0;
  let part1Correct = 0;
  let part2CorrectCount = 0;
  let part3Correct = 0;

  exam.questions.forEach(q => {
    const ans = userAnswers[q.id];
    if (q.part === 1) {
      if (ans && ans === q.correctAnswer) {
        totalScore += 0.25;
        part1Correct++;
      }
    } else if (q.part === 2) {
      if (ans && typeof ans === 'object' && q.options) {
        let matchedBranches = 0;
        q.options.forEach(opt => {
          const userChoice = ans[opt.letter];
          if (userChoice !== undefined && userChoice === opt.isCorrect) {
            matchedBranches++;
          }
        });
        if (matchedBranches === 1) totalScore += 0.1;
        else if (matchedBranches === 2) totalScore += 0.25;
        else if (matchedBranches === 3) totalScore += 0.5;
        else if (matchedBranches === 4) {
          totalScore += 1.0;
          part2CorrectCount++;
        }
      }
    } else if (q.part === 3) {
      if (ans !== undefined && String(ans).trim() !== '') {
        const cleanUser = String(ans).trim().replace(',', '.');
        const cleanCorrect = String(q.correctAnswer || '').trim().replace(',', '.');
        if (cleanUser === cleanCorrect) {
          totalScore += 0.25;
          part3Correct++;
        }
      }
    }
  });

  return {
    score: Math.round(totalScore * 100) / 100,
    part1Correct,
    part2CorrectCount,
    part3Correct,
    totalQuestions: exam.questions.length
  };
}

function shuffleArray<T>(array: T[]): T[] {
  const arr = [...array];
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

export function shuffleChuong4Exam(exam: Chuong4Exam): Chuong4Exam {
  const p1 = exam.questions.filter(q => q.part === 1);
  const p2 = exam.questions.filter(q => q.part === 2);
  const p3 = exam.questions.filter(q => q.part === 3);

  const shuffledP1 = shuffleArray(p1).map(q => {
    if (q.options && q.options.length > 0) {
      const origCorrectOpt = q.options.find(o => o.letter === q.correctAnswer || o.isCorrect);
      const origCorrectText = origCorrectOpt?.text;
      const shuffledOptions = shuffleArray(q.options);
      const letters = ["A", "B", "C", "D"];
      shuffledOptions.forEach((opt, idx) => {
        opt.letter = letters[idx];
      });
      const newCorrectOpt = shuffledOptions.find(o => (origCorrectText && o.text === origCorrectText) || o.isCorrect);
      const newCorrectLetter = newCorrectOpt?.letter || "A";
      shuffledOptions.forEach(opt => {
        opt.isCorrect = (opt.letter === newCorrectLetter);
      });
      return {
        ...q,
        options: shuffledOptions,
        correctAnswer: newCorrectLetter
      };
    }
    return q;
  });

  const shuffledP2 = shuffleArray(p2).map(q => {
    if (q.options && q.options.length > 0) {
      const shuffledOptions = shuffleArray(q.options);
      const letters = ["a", "b", "c", "d"];
      shuffledOptions.forEach((opt, idx) => {
        opt.letter = letters[idx];
      });
      return {
        ...q,
        options: shuffledOptions
      };
    }
    return q;
  });

  const shuffledP3 = shuffleArray(p3);

  const finalQuestions = [...shuffledP1, ...shuffledP2, ...shuffledP3].map((q, idx) => ({
    ...q,
    displayNumber: idx + 1
  }));

  return {
    ...exam,
    questions: finalQuestions
  };
}

export function getChuong4RankTitle(xp: number): string {
  if (xp >= 5000) return "👑 Thủ Khoa Hóa 12";
  if (xp >= 3000) return "🧶 Bậc Thầy Polymer & Vật Liệu";
  if (xp >= 1500) return "🔬 Chuyên Gia Chất Dẻo & Tơ";
  if (xp >= 500) return "🥇 Cao Thủ Cao Su & Keo Dán";
  return "🥉 Tân Binh Hóa Học";
}
